mapper.select:
SELECT 
    RULE_ID, RULE_CODE, RULE_NAME, RULE_TYPE, TRANSACTION_TYPE,
    RULE_CONDITION, RULE_ACTION, PRIORITY, IS_ENABLED,
    BOOK_ID, TENANT_ID, VERSION, CREATE_TIME, UPDATE_TIME, CREATOR, UPDATER
FROM T_ACCOUNTING_RULE
WHERE IS_DELETED = 0

    AND RULE_CODE LIKE '%' || #{param.ruleCode} || '%'


    AND RULE_NAME LIKE '%' || #{param.ruleName} || '%'


    AND RULE_TYPE = #{param.ruleType}


    AND TRANSACTION_TYPE = #{param.transactionType}


    AND IS_ENABLED = #{param.isEnabled}


    AND BOOK_ID = #{param.bookId}


    AND TENANT_ID = #{param.tenantId}

ORDER BY PRIORITY ASC, CREATE_TIME DESC

SELECT * FROM T_ACCOUNTING_RULE
WHERE RULE_CODE = #{ruleCode}
AND BOOK_ID = #{bookId}
AND TENANT_ID = #{tenantId}
AND IS_DELETED = 0

    AND RULE_ID != #{excludeId}

AND ROWNUM = 1

SELECT 
    RULE_ID, RULE_CODE, RULE_NAME, RULE_TYPE, TRANSACTION_TYPE,
    RULE_CONDITION, RULE_ACTION, PRIORITY, IS_ENABLED,
    BOOK_ID, TENANT_ID, VERSION, CREATE_TIME, UPDATE_TIME, CREATOR, UPDATER
FROM T_ACCOUNTING_RULE
WHERE RULE_TYPE = #{ruleType}
AND BOOK_ID = #{bookId}
AND TENANT_ID = #{tenantId}
AND IS_DELETED = 0
ORDER BY PRIORITY ASC, CREATE_TIME DESC

SELECT 
    RULE_ID, RULE_CODE, RULE_NAME, RULE_TYPE, TRANSACTION_TYPE,
    RULE_CONDITION, RULE_ACTION, PRIORITY, IS_ENABLED,
    BOOK_ID, TENANT_ID, VERSION, CREATE_TIME, UPDATE_TIME, CREATOR, UPDATER
FROM T_ACCOUNTING_RULE
WHERE TRANSACTION_TYPE = #{transactionType}
AND BOOK_ID = #{bookId}
AND TENANT_ID = #{tenantId}
AND IS_DELETED = 0
ORDER BY PRIORITY ASC, CREATE_TIME DESC

SELECT 
    RULE_ID, RULE_CODE, RULE_NAME, RULE_TYPE, TRANSACTION_TYPE,
    RULE_CONDITION, RULE_ACTION, PRIORITY, IS_ENABLED,
    BOOK_ID, TENANT_ID, VERSION, CREATE_TIME, UPDATE_TIME, CREATOR, UPDATER
FROM T_ACCOUNTING_RULE
WHERE IS_ENABLED = #{isEnabled}
AND BOOK_ID = #{bookId}
AND TENANT_ID = #{tenantId}
AND IS_DELETED = 0
ORDER BY PRIORITY ASC, CREATE_TIME DESC

