FROM T_ACCOUNTING_RULE
WHERE BOOK_ID = #{bookId}
AND TENANT_ID = #{tenantId}
AND IS_DELETED = 0
ORDER BY RULE_TYPE

SELECT DISTINCT TRANSACTION_TYPE
FROM T_ACCOUNTING_RULE
WHERE BOOK_ID = #{bookId}
AND TENANT_ID = #{tenantId}
AND IS_DELETED = 0
ORDER BY TRANSACTION_TYPE
